(() => {
const workouts = {
 A: {title:'Superiores', focus:'Peito, costas, ombros e braços', icon:'↗', exercises:[['supino-maquina','Supino máquina','10–12','Peitoral, tríceps e ombros','Ajuste o banco para as alças ficarem na linha do peito. Empurre e retorne com controle.','Mantenha as costas apoiadas e não trave os cotovelos.'],['puxada-frontal','Puxada frontal','10–12','Costas e bíceps','Puxe a barra à frente até a parte alta do peito e retorne devagar.','Evite balançar o tronco ou puxar atrás da nuca.'],['remada-baixa','Remada baixa','10–12','Costas e bíceps','Com o tronco estável, puxe a alça em direção ao abdômen e retorne.','Evite arredondar as costas ou usar impulso.'],['desenvolvimento-maquina','Desenvolvimento máquina','10–12','Ombros e tríceps','Ajuste o banco e empurre as alças para cima, retornando com controle.','Use amplitude confortável, sem arquear as costas.'],['triceps-polia','Tríceps polia','10–12','Tríceps','Mantenha os cotovelos próximos do corpo e estenda os braços na polia.','Não use o peso do tronco para empurrar.'],['rosca-halteres','Rosca halteres','10–12','Bíceps','Flexione os cotovelos levando os halteres para cima e desça lentamente.','Mantenha o tronco parado e os punhos alinhados.']]},
 B: {title:'Pernas e glúteos',focus:'Base forte, movimento com controle',icon:'↓',exercises:[['leg-press','Leg press 45°','10–12','Quadríceps e glúteos','Apoie os pés na plataforma, flexione os joelhos e empurre com controle.','Mantenha quadril e costas apoiados; não trave os joelhos.'],['elevacao-pelvica','Elevação pélvica','10–12','Glúteos','Com os pés apoiados, eleve o quadril e retorne lentamente.','Evite exagerar na extensão da lombar.'],['mesa-flexora','Mesa flexora','10–12','Posteriores das coxas','Ajuste o equipamento e flexione os joelhos, aproximando os calcanhares.','Mantenha o quadril apoiado e evite impulso.'],['cadeira-extensora','Cadeira extensora','10–12','Quadríceps','Alinhe os joelhos ao eixo da máquina e estenda as pernas com controle.','Ajuste o apoio e evite movimentos bruscos.'],['panturrilha-sentado','Panturrilha sentado','12–15','Panturrilhas','Eleve os calcanhares e retorne devagar, mantendo os pés apoiados na base.','Não quique e use amplitude confortável.'],['prancha','Prancha','20–30 segundos','Abdômen e estabilizadores','Apoie antebraços e pontas dos pés, mantendo o corpo alinhado.','Respire normalmente e evite deixar o quadril cair.','tempo']]},
 C: {title:'Corpo inteiro',focus:'Um pouco de tudo. Por vocês.',icon:'✳',exercises:[['agachamento-halter','Agachamento com halter','10–12','Quadríceps e glúteos','Segure o halter próximo ao peito, flexione quadril e joelhos e retorne.','Mantenha os pés apoiados e os joelhos alinhados.'],['remada-articulada','Remada articulada','10–12','Costas e bíceps','Ajuste o apoio e puxe as alças em direção ao tronco.','Mantenha o peito apoiado e evite elevar os ombros.'],['supino-inclinado','Supino inclinado','10–12','Peitoral, ombros e tríceps','No banco inclinado, empurre a carga para cima e retorne com controle.','Mantenha os pés firmes e use amplitude confortável.'],['cadeira-abdutora','Cadeira abdutora','12–15','Glúteos','Sentado com as costas apoiadas, afaste os joelhos e retorne lentamente.','Evite impulso e não force além da amplitude confortável.'],['terra-romeno','Levantamento terra romeno com halteres','8–10','Posteriores e glúteos','Com joelhos levemente flexionados, leve o quadril para trás e desça os halteres próximos às pernas.','Mantenha a coluna estável; pare antes de perder o alinhamento.'],['dead-bug','Dead bug','8–10 por lado','Abdômen e estabilizadores','Deitado, eleve braços e pernas. Estenda braço e perna opostos alternadamente.','Mantenha o tronco estável e não arqueie a lombar.','repeticoes']]}
};
const today = () => new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const weekday = date => new Date(date+'T12:00:00-03:00').getUTCDay();
const recommended = date => ({1:'B',3:'A',5:'C'})[weekday(date)] || 'B';
const sessionKey = (profile,date,workout) => `${profile}:${date}:${workout}`;
const progress = session => Math.round(Object.values(session?.sets || {}).filter(s=>s.done).length/12*100);

function lastExerciseSession(sessions, profile, date, exerciseId, excludedKey) {
  const candidates = Object.entries(sessions)
    .filter(([key, session]) => key !== excludedKey && session.profile === profile && session.date <= date)
    .sort(([aKey, a], [bKey, b]) => b.date.localeCompare(a.date) || Number(bKey.split(':')[3] || 0) - Number(aKey.split(':')[3] || 0));
  for (const [, session] of candidates) {
    const sets = [0, 1].map(index => ({index, ...session.sets[`${exerciseId}:${index}`]})).filter(set => set.done);
    if (sets.length) return {date: session.date, sets};
  }
  return null;
}

function workoutSummary(sessions, profile, start, end) {
  const summary = {registered: 0, complete: 0, partial: 0, ongoing: 0};
  for (const [key, session] of Object.entries(sessions)) {
    if (session.profile !== profile || session.date < start || session.date >= end) continue;
    if (key === sessionKey(session.profile, session.date, session.workout)) {
      summary.ongoing++;
      continue;
    }
    summary.registered++;
    if (progress(session) === 100) summary.complete++;
    else summary.partial++;
  }
  return summary;
}

const exercisePhotos={
  "supino-maquina": "Machine_Bench_Press",
  "puxada-frontal": "Wide-Grip_Lat_Pulldown",
  "remada-baixa": "Seated_Cable_Rows",
  "desenvolvimento-maquina": "Machine_Shoulder_Military_Press",
  "triceps-polia": "Triceps_Pushdown",
  "rosca-halteres": "Dumbbell_Bicep_Curl",
  "leg-press": "Leg_Press",
  "elevacao-pelvica": "Barbell_Hip_Thrust",
  "mesa-flexora": "Lying_Leg_Curls",
  "cadeira-extensora": "Leg_Extensions",
  "panturrilha-sentado": "Seated_Calf_Raise",
  "prancha": "Plank",
  "agachamento-halter": "Goblet_Squat",
  "remada-articulada": "Leverage_Iso_Row",
  "supino-inclinado": "Incline_Dumbbell_Press",
  "cadeira-abdutora": "Thigh_Abductor",
  "dead-bug": "Dead_Bug"
};

const STORAGE_KEY='nosso-treino:v1';
let workspaceAdapter=null;
function useWorkspace(adapter){workspaceAdapter=adapter;}
function load(storage=localStorage){if(workspaceAdapter)return workspaceAdapter.load();const raw=storage.getItem(STORAGE_KEY); if(!raw)return {sessions:{}};const data=JSON.parse(raw);if(!data || !data.sessions || typeof data.sessions!=='object' || Array.isArray(data.sessions))throw new Error('Backup inválido');return data;}
function save(data,storage=localStorage){if(workspaceAdapter){workspaceAdapter.save(data);return;}storage.setItem(STORAGE_KEY,JSON.stringify(data));}
function validateBackup(data){
 if(data?.version!==1||!data.sessions||typeof data.sessions!=='object'||Array.isArray(data.sessions))throw Error('Formato de backup não reconhecido.');
 for(const [key,s] of Object.entries(data.sessions)){
  const base=s&&s.profile+':'+s.date+':'+s.workout;
  if(!s||!['Caio','Nicolli'].includes(s.profile)||!Object.hasOwn(workouts,s.workout)||!/^\d{4}-\d{2}-\d{2}$/.test(s.date)||!Number.isFinite(Date.parse(s.date))||new Date(s.date).toISOString().slice(0,10)!==s.date||!(key===base||key.startsWith(base+':')&&/^[1-9]\d*$/.test(key.slice(base.length+1)))||!s.sets||typeof s.sets!=='object'||Array.isArray(s.sets))throw Error('Registro inválido.');
  for(const [id,v] of Object.entries(s.sets)){
   const [exercise,index]=id.split(':');
   if(!workouts[s.workout].exercises.some(e=>e[0]===exercise)||!['0','1'].includes(index)||id!==exercise+':'+index||!v||typeof v.done!=='boolean')throw Error('Série inválida.');
   for(const f of ['weight','reps'])if(v[f]!==''&&(!['string','number'].includes(typeof v[f])||!Number.isFinite(Number(v[f]))||Number(v[f])<0||Number(v[f])>999||f==='reps'&&!Number.isInteger(Number(v[f]))))throw Error('Valor inválido na série.');
  }
 }
 return data.sessions;
}

const PROFILE_KEY='nosso-treino:perfil';
function loadProfile(storage=localStorage) {
  try {
    const profile=storage.getItem(PROFILE_KEY);
    return ['Caio','Nicolli'].includes(profile)?profile:'Caio';
  } catch { return 'Caio'; }
}
function saveProfile(profile,storage=localStorage) {
  if (!['Caio','Nicolli'].includes(profile)) throw new Error('Perfil inválido.');
  storage.setItem(PROFILE_KEY,profile);
}

const cloud=globalThis.NossoCloud;
let data;let storageError=false;try{data=load();}catch{data={sessions:{}};storageError=true;}
let profile=loadProfile(), date=today(), selected=recommended(date), view='inicio';
let openedSessionKey=null;
let deletedRecord=null, evolutionExercise='supino-maquina';
let editDraft=null, returnContext=null;
function leaveRecord(){if(editDraft&&!confirm('Descartar alterações não salvas?'))return false;editDraft=null;openedSessionKey=null;if(returnContext){({date,selected}=returnContext);returnContext=null;}return true;}

const historyFilters={workout:'',from:'',to:''};
const savedTime=session=>session.savedAt && Number.isFinite(Date.parse(session.savedAt)) ? new Date(session.savedAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'}) : 'horário não registrado';
const recordKey=session=>Object.keys(data.sessions).find(key=>data.sessions[key]===session);
const recordLabel=session=>recordKey(session)===sessionKey(session.profile,session.date,session.workout)?'Em andamento':progress(session)===100?'Completo':'Parcial';
const app=document.querySelector('#app'), status=document.querySelector('#save-status');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatted=d=>new Date(d+'T12:00:00-03:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});
const records=()=>Object.values(data.sessions).filter(s=>s.profile===profile).sort((a,b)=>b.date.localeCompare(a.date)||(Date.parse(b.savedAt)||0)-(Date.parse(a.savedAt)||0)||Number(recordKey(b).split(':')[3]||0)-Number(recordKey(a).split(':')[3]||0));
const current=()=>editDraft || (openedSessionKey ? data.sessions[openedSessionKey] : data.sessions[sessionKey(profile,date,selected)] || data.drafts?.[sessionKey(profile,date,selected)]);
function persist(){try{if(storageError)throw Error();save(data);status.textContent=cloud?.active?'● '+cloud.notice:'● Salvo neste dispositivo';status.classList.toggle('error',Boolean(cloud?.conflict));return true;}catch{status.textContent='⚠ Não foi possível salvar. Exporte um backup.';status.classList.add('error');return false;}}
function picker(){return `<div class="toolbar"><div class="profiles" aria-label="Perfil ativo">${['Caio','Nicolli'].map(p=>`<button data-profile="${p}" class="${profile===p?'active':''}" aria-pressed="${profile===p}"><span class="avatar ${p==='Nicolli'?'pink':''}">${p[0]}</span>${p}</button>`).join('')}</div><label class="date">Data do treino<input type="date" id="date" value="${date}" max="${today()}" ${openedSessionKey?'disabled':''}></label>${!openedSessionKey&&date!==today()?'<button class="secondary" id="return-today">Voltar para hoje</button>':''}</div>`;}
function cards(){return `<div class="workouts">${Object.entries(workouts).map(([id,w])=>`<button class="workout-card" data-workout="${id}"><span class="letter">${id}</span><span><strong>${w.title}</strong><small>6 exercícios · 2 séries cada</small></span><span class="arrow">↗</span></button>`).join('')}</div>`;}
function home(){const list=records(), day=weekday(date), rec=recommended(date); const monday=new Date(date+'T12:00:00-03:00');monday.setUTCDate(monday.getUTCDate()-((day+6)%7));const start=monday.toISOString().slice(0,10);const end=new Date(monday);end.setUTCDate(end.getUTCDate()+7);const summary=workoutSummary(data.sessions,profile,start,end.toISOString().slice(0,10));return `<div class="home-screen">${picker()}<div class="intro"><span class="eyebrow">SEU ESPAÇO DE EVOLUÇÃO</span><h1>Vamos nessa, ${profile}<span class="mint">.</span></h1><p>Um treino de cada vez. Uma conquista de vocês.</p></div><section class="hero"><div><span class="pill"><span class="status-dot" aria-hidden="true"></span>${[1,3,5].includes(day)?'TREINO DO DIA':day===4?'HOJE É DIA DE FUTEBOL':'DIA DE RECUPERAR'}</span><h2>${[1,3,5].includes(day)?workouts[rec].title:day===4?'Bola em jogo.':'Respire. Recupere.'}</h2><p>${[1,3,5].includes(day)?'6 exercícios · 2 séries por exercício':day===4?'Futebol das 20h às 21h.':'Descanso ou atividade leve, no seu ritmo.'}</p><button class="primary" data-workout="${rec}">Iniciar treino ${rec} <span>↗</span></button><small>Você pode escolher qualquer treino abaixo.</small></div><div class="hero-art" aria-hidden="true">${[1,3,5].includes(day)?rec:'↗'}</div></section><div class="stats"><article><span>ESSA SEMANA</span><strong>${summary.registered}<small> treinos registrados</small></strong><small class="summary-detail">${summary.complete} completos · ${summary.partial} parciais</small><div class="track"><i style="width:${Math.min(summary.registered/3*100,100)}%"></i></div><small class="summary-detail">Meta semanal: 3 registros${summary.ongoing?` · ${summary.ongoing} em andamento`:""}</small></article><article><span>ÚLTIMO TREINO</span><strong>${list[0]?`Treino ${list[0].workout}`:'Seu primeiro passo'}</strong><small>${list[0]?`${formatted(list[0].date)} · ${progress(list[0])}% concluído`:'Tudo pronto para começar'}</small></article></div><div class="section-title"><div><span class="eyebrow">SUA ROTINA</span><h2>Escolha seu treino</h2></div><span>3 fichas</span></div>${cards()}<aside><span>✦</span><div><strong>Antes de começar</strong><p>Aqueça por 5–8 minutos. Priorize a execução e progrida gradualmente. Evite a falha nas primeiras semanas.</p></div></aside></div>`;}

function previousExercise(exercise) {
  if (openedSessionKey) return '';
  const previous = lastExerciseSession(data.sessions, profile, date, exercise[0], sessionKey(profile,date,selected));
  if (!previous) return '<div class="last-exercise">Sem execução anterior registrada para este exercício.</div>';
  const lines = previous.sets.map(set => {
    const amount = esc(set.reps === '' || set.reps == null ? '—' : set.reps);
    const value = exercise[6] === 'tempo' ? amount + ' s' : exercise[6] ? amount + ' rep. por lado' : esc(set.weight === '' || set.weight == null ? '—' : set.weight) + ' kg × ' + amount + ' rep.';
    return '<span>Série ' + (set.index + 1) + ': ' + value + '</span>';
  }).join('');
  return '<div class="last-exercise"><strong>Última vez · ' + formatted(previous.date) + ' · ' + previous.date.slice(0,4) + '</strong>' + lines + '</div>';
}

function training(){const w=workouts[selected], s=current();return `<section class="training-controls" aria-label="Controles do treino"><div class="training-controls-row"><div class="profiles" aria-label="Trocar perfil durante o treino">${['Caio','Nicolli'].map(p=>`<button data-profile="${p}" class="${profile===p?'active':''}" aria-pressed="${profile===p}">${p}</button>`).join('')}</div><span class="compact-progress">Treino ${selected} · <strong id="sticky-percent">${progress(s)}%</strong></span><button id="save-workout" class="primary">Salvar e encerrar treino</button></div><p id="save-workout-message" role="status" aria-live="polite"></p><div id="saved-workout-actions"></div></section>${picker()}${editDraft?'<aside><div><strong>Editando registro · alterações ainda não salvas</strong><p>Revise os campos e salve ou cancele.</p><button class="primary" id="save-edit">Salvar alterações</button> <button class="secondary" id="cancel-edit">Cancelar</button></div></aside>':''}${openedSessionKey&&!editDraft?'<aside><div><strong>Registro salvo · somente leitura</strong><p>Estas são as séries registradas neste treino.</p><button class="secondary" id="edit-record">Editar registro</button> <button class="secondary" data-view="historico">Voltar ao histórico</button></div></aside>':''}<div class="tabs">${Object.keys(workouts).map(id=>`<button data-workout="${id}" class="${id===selected?'active':''}">Treino ${id}</button>`).join('')}</div><div class="intro"><span class="eyebrow">TREINO ${selected} · ${profile.toUpperCase()} · ${formatted(date)}</span><h1>${w.title}</h1><p>${w.focus}</p></div><div class="progress-head"><span>Seu progresso</span><strong id="percent">${progress(s)}%</strong></div><div class="track"><i id="progress-bar" style="width:${progress(s)}%"></i></div><p class="hint">Descanso entre séries: 60–120 segundos, adaptável.</p>${w.exercises.map((e,i)=>`<article class="exercise"><div class="exercise-head"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h2>${e[1]}</h2><p>2 séries · ${e[2]}</p></div><button class="instruction" data-instruction="${e[0]}" aria-label="Ver execução: ${e[1]}">ⓘ</button></div>${previousExercise(e)}<div class="set-grid labels"><span>SÉRIE</span><span>${e[6]?'SEM CARGA':'CARGA · KG'}</span><span>${e[6]==='tempo'?'TEMPO · S':'REPETIÇÕES'}</span><span>FEITO</span></div>${[0,1].map(n=>{const v=s?.sets[`${e[0]}:${n}`]||{weight:'',reps:'',done:false};return `<div class="set-grid"><span class="set-number">${n+1}</span>${e[6]?'<span class="no-weight">—</span>':`<input aria-label="${e[1]}, série ${n+1}, carga em kg" type="number" inputmode="decimal" min="0" max="999" step="0.5" data-set="${e[0]}:${n}" data-field="weight" value="${v.weight}">`}<input aria-label="${e[1]}, série ${n+1}, ${e[6]==='tempo'?'segundos':'repetições'}" type="number" inputmode="numeric" min="0" max="999" step="1" data-set="${e[0]}:${n}" data-field="reps" value="${v.reps}"><input type="checkbox" aria-label="Concluir ${e[1]}, série ${n+1}" data-set="${e[0]}:${n}" data-field="done" ${v.done?'checked':''}></div>`;}).join('')}<p class="field-error" id="error-${e[0]}" role="alert"></p>${!openedSessionKey||editDraft?`<button class="secondary" data-copy-series="${e[0]}">Copiar série 1 para série 2</button>`:''}<small class="exercise-done" id="done-${e[0]}">${[0,1].every(n=>s?.sets[`${e[0]}:${n}`]?.done)?'✓ Exercício concluído':''}</small></article>`).join('')}<div id="complete" class="completion" ${progress(s)===100?'':'hidden'}>✓ Treino concluído. Mais um passo por você!</div><p class="hint">${editDraft?'As alterações aguardam o botão “Salvar alterações”. Cancelar preserva o registro original.':openedSessionKey?'Você está consultando um registro salvo. Use “Editar registro” para corrigir seus dados.':'Suas alterações são salvas automaticamente neste dispositivo. Use “Salvar e encerrar treino” para guardar o resultado no histórico e limpar as marcações, mesmo com exercícios pendentes.'}</p>`;}
function history(){const filtered=records().filter(s=>(!historyFilters.workout||s.workout===historyFilters.workout)&&(!historyFilters.from||s.date>=historyFilters.from)&&(!historyFilters.to||s.date<=historyFilters.to));return `${picker()}<div class="intro"><span class="eyebrow">UM PASSO DE CADA VEZ</span><h1>Seu histórico<span class="mint">.</span></h1><p>Os registros de ${profile}, completos ou em andamento.</p></div><div class="history-filters"><label>Treino<select id="history-workout"><option value="">Todos</option>${['A','B','C'].map(id=>`<option value="${id}" ${historyFilters.workout===id?'selected':''}>Treino ${id}</option>`).join('')}</select></label><label>De<input type="date" id="history-from" value="${historyFilters.from}"></label><label>Até<input type="date" id="history-to" value="${historyFilters.to}"></label><button class="secondary" id="clear-history-filters">Limpar filtros</button></div><p class="hint">${filtered.length} registro(s) encontrado(s). O período considera a data do treino.</p>${deletedRecord&&deletedRecord.session.profile===profile?'<button class="secondary" id="undo-delete">Desfazer última exclusão</button>':''}<p id="history-message" role="status" aria-live="polite"></p>${filtered.length?filtered.map(s=>`<details class="history"><summary><span><strong>Treino ${s.workout} · ${workouts[s.workout].title}</strong><small>${formatted(s.date)} · ${s.date.slice(0,4)} · Registro ${esc(recordKey(s).split(':')[3]||'em andamento')}</small><small>Salvo em: ${esc(savedTime(s))}</small></span><span class="badge">${recordLabel(s)} · ${progress(s)}%</span></summary>${workouts[s.workout].exercises.map(e=>`<div class="history-exercise"><strong>${e[1]}</strong>${[0,1].map(n=>{const v=s.sets[`${e[0]}:${n}`];return `<small>Série ${n+1}: ${v?`${v.done?'✓':'○'} ${!e[6]?(v.weight||'—')+' kg × ':''}${v.reps||'—'} ${e[6]==='tempo'?'s':'rep.'}`:'não registrada'}</small>`;}).join('')}</div>`).join('')}<button class="secondary" data-resume="${esc(Object.keys(data.sessions).find(key=>data.sessions[key]===s))}">${recordLabel(s)==='Em andamento'?'Continuar treino':'Abrir registro'}</button> <button class="secondary danger" data-delete-session="${esc(Object.keys(data.sessions).find(key=>data.sessions[key]===s))}">Excluir treino</button></details>`).join(''):'<div class="empty">◷<h2>Nenhum treino encontrado.</h2><p>Registre um treino ou ajuste os filtros para consultar o histórico.</p></div>'}<aside><div><strong>Seus dados, com você</strong><p id="last-backup">Última exportação solicitada: ${data.lastBackupAt?esc(savedTime({savedAt:data.lastBackupAt})):'nenhuma'}. Confira o arquivo na pasta de downloads.</p><p>${cloud?.active?'O backup inclui apenas os registros desta conta.':'O backup inclui os dois perfis locais.'} Guarde o arquivo em um local privado. A importação preserva registros que já existem.</p><button class="secondary" id="export">Exportar backup</button> <label class="secondary file">Importar backup<input type="file" id="import" accept="application/json"></label><p id="backup-message" role="status"></p></div></aside>`;}
function evolution(){const monthStart=date.slice(0,7)+'-01';const nextMonth=new Date(monthStart+'T12:00:00Z');nextMonth.setUTCMonth(nextMonth.getUTCMonth()+1);const summary=workoutSummary(data.sessions,profile,monthStart,nextMonth.toISOString().slice(0,10));return `${picker()}<div class="intro"><span class="eyebrow">CONSISTÊNCIA VIRA EVOLUÇÃO</span><h1>Cada passo conta<span class="mint">.</span></h1><p>${summary.registered} treinos registrados no mês selecionado.<br>${summary.complete} completos · ${summary.partial} parciais${summary.ongoing?` · ${summary.ongoing} em andamento`:""}.</p></div><label class="select-label">Exercício<select id="exercise-select">${Object.values(workouts).flatMap(w=>w.exercises).map(e=>`<option value="${e[0]}" ${evolutionExercise===e[0]?'selected':''}>${e[1]}</option>`).join('')}</select></label><div id="chart"></div><aside><div><strong>Compare o mesmo movimento</strong><p>As cargas são comparadas apenas dentro de cada exercício. Nenhuma mudança na ficha é feita automaticamente.</p></div></aside>`;}
function chart(id){
 const exercise=Object.values(workouts).flatMap(w=>w.exercises).find(e=>e[0]===id);if(!exercise)return;
 const field=exercise[6]?'reps':'weight',unit=exercise[6]==='tempo'?'s':exercise[6]?'rep./lado':'kg';
 const entries=records().filter(s=>s.date.slice(0,7)===date.slice(0,7)).slice().reverse().map(s=>({date:s.date,values:Object.entries(s.sets).filter(([k,v])=>k.startsWith(id+':')&&v.done&&v[field]!==''&&Number(v.reps)>0).map(([,v])=>Number(v[field]))})).filter(s=>s.values.length).map(s=>({...s,value:Math.max(...s.values)}));
 const best=Math.max(0,...entries.map(e=>e.value)),last=entries.at(-1),prev=entries.at(-2);
 document.querySelector('#chart').innerHTML='<p class="hint">Período: '+date.slice(0,7).split('-').reverse().join('/')+' · Apenas séries concluídas. Maior valor de cada sessão.</p>'+(entries.length?`<div class="stats"><article><span>MELHOR NO MÊS</span><strong>${best} <small>${unit}</small></strong></article><article><span>ÚLTIMA EXECUÇÃO NO MÊS</span><strong>${last.value} <small>${unit}</small></strong><small>${prev?`${last.value-prev.value>=0?'+':''}${last.value-prev.value} ${unit} em relação à anterior no mês`:'Primeiro registro do mês'}</small></article></div><section class="chart"><h2>${exercise[6]==='tempo'?'Tempo':exercise[6]?'Repetições':'Carga'} por sessão</h2>${entries.map(e=>`<div class="bar-row"><small>${formatted(e.date)}</small><div><i style="width:${best?e.value/best*100:0}%"></i></div><strong>${e.value} ${unit}</strong></div>`).join('')}</section>`:'<div class="empty"><h2>Sem registros neste mês.</h2><p>Escolha outra data ou registre séries deste exercício.</p></div>');
}
function render(){app.innerHTML=({inicio:home,treino:training,historico:history,evolucao:evolution})[view]();if(openedSessionKey&&view==='treino'){app.querySelectorAll('input[data-set]').forEach(input=>input.disabled=!editDraft);document.querySelector('#save-workout').hidden=true;}if(cloud?.active)app.querySelectorAll('[data-profile]').forEach(button=>{button.disabled=button.dataset.profile!==cloud.profile;button.title=button.disabled?'Saia da conta atual para trocar de usuário.':'';});document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false');});if(view==='evolucao')chart(document.querySelector('#exercise-select').value);if(storageError){status.textContent='⚠ Armazenamento indisponível ou inválido. Exporte um backup.';status.classList.add('error');return false;}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(cloud?.busy&&!['open-account','close-account'].includes(b.id))return;if(['open-account','close-account','cloud-retry','cloud-refresh','cloud-migrate','cloud-logout'].includes(b.id)){handleAccountClick(e);return;}if(b.id==='undo-delete'&&deletedRecord&&deletedRecord.session.profile===profile){const {key,session}=deletedRecord;if(Object.hasOwn(data.sessions,key)){document.querySelector('#history-message').textContent='Não foi possível restaurar: já existe um registro com essa identificação.';return;}data.sessions[key]=session;if(persist()){deletedRecord=null;render();document.querySelector('#history-message').textContent='Registro restaurado.';}else{delete data.sessions[key];document.querySelector('#history-message').textContent='Não foi possível restaurar. Tente novamente.';}return;}
if(b.dataset.copySeries){if(openedSessionKey&&!editDraft)return;const id=b.dataset.copySeries;const invalid=[...app.querySelectorAll('input[type=number]')].find(input=>!input.checkValidity());if(invalid){invalid.reportValidity();return;}const source=current()?.sets[id+':0'];if(!source||source.reps===''){document.querySelector('#error-'+id).textContent='Preencha a primeira série antes de copiar.';return;}const key=sessionKey(profile,date,selected);const session=editDraft||(data.sessions[key]??=JSON.parse(JSON.stringify(current())));session.sets[id+':1']={...source,done:false};if(!editDraft)persist();render();return;}
if(b.id==='return-today'){if(!leaveRecord())return;date=today();render();return;}
if(b.id==='edit-record'&&openedSessionKey){editDraft=JSON.parse(JSON.stringify(data.sessions[openedSessionKey]));render();return;}
if(b.id==='cancel-edit'){editDraft=null;render();return;}
if(b.id==='save-edit'&&editDraft&&openedSessionKey){const invalid=[...app.querySelectorAll('input[type=number]')].find(input=>!input.checkValidity());if(invalid){invalid.reportValidity();return;}const original=data.sessions[openedSessionKey];data.sessions[openedSessionKey]={...editDraft,updatedAt:new Date().toISOString()};if(persist()){editDraft=null;render();document.querySelector('#save-workout-message').textContent='Alterações salvas neste registro.';}else{data.sessions[openedSessionKey]=original;document.querySelector('#save-workout-message').textContent='Não foi possível salvar. Suas alterações continuam disponíveis para tentar novamente.';}return;}
if(b.id==='clear-history-filters'){historyFilters.workout='';historyFilters.from='';historyFilters.to='';render();return;}if(b.dataset.view){if(!leaveRecord())return;view=b.dataset.view;render();window.scrollTo(0,0);}if(b.dataset.profile){if(cloud?.active&&b.dataset.profile!==cloud.profile){showAccount('Saia da conta atual e entre com a conta do outro perfil.');return;}if(!['Caio','Nicolli'].includes(b.dataset.profile))return;if(!leaveRecord())return;profile=b.dataset.profile;render();try{saveProfile(profile);}catch{status.textContent='⚠ Perfil alterado, mas não foi possível lembrar a escolha neste dispositivo.';status.classList.add('error');}}if(b.dataset.workout){if(!leaveRecord())return;selected=b.dataset.workout;view='treino';render();window.scrollTo(0,0);}if(b.dataset.deleteSession){const key=b.dataset.deleteSession;const session=data.sessions[key];if(!session||session.profile!==profile)return;if(!confirm('Excluir o treino '+session.workout+' de '+formatted(session.date)+' de '+profile+' (registro '+(key.split(':')[3]||'em andamento')+', '+savedTime(session)+')? Essa ação não pode ser desfeita.'))return;delete data.sessions[key];if(persist()){deletedRecord={key,session};render();document.querySelector('#history-message').textContent='Treino excluído do histórico.';}else{data.sessions[key]=session;document.querySelector('#history-message').textContent='Não foi possível excluir. O registro foi mantido.';}return;}if(b.dataset.resume){const session=data.sessions[b.dataset.resume];if(!session||session.profile!==profile)return;if(!leaveRecord())return;returnContext={date,selected};openedSessionKey=b.dataset.resume===sessionKey(session.profile,session.date,session.workout)?null:b.dataset.resume;date=session.date;selected=session.workout;view='treino';render();window.scrollTo(0,0);}if(b.dataset.instruction){const ex=Object.values(workouts).flatMap(w=>w.exercises).find(x=>x[0]===b.dataset.instruction);document.querySelector('#instruction-body').innerHTML=`<span class="eyebrow">GUIDE D’EXÉCUTION</span><h2 id="guide-title">${ex[1]}</h2>${exercisePhotos[ex[0]]?`<div class="exercise-photos">${[0,1].map(i=>`<figure><img src="assets/exercises/${ex[0]}-${i}.jpg" alt="${ex[1]} — referência visual ${i+1}" width="850" height="567"><figcaption>Posição ${i+1}</figcaption></figure>`).join('')}</div><p class="photo-credit">Referência visual: Free Exercise DB · Unlicense. O modelo do equipamento pode variar.</p>`:'<p class="photo-credit">Foto de referência ainda não disponível para este exercício.</p>'}<p>${ex[4]}</p><h3>Músculos trabalhados</h3><p>${ex[3]}</p><h3>Cuidados na execução</h3><p>${ex[5]} Em caso de dor, interrompa e procure orientação profissional.</p>` .replace('GUIDE D’EXÉCUTION','GUIA DE EXECUÇÃO');document.querySelector('dialog').showModal();document.querySelector('dialog').scrollTop=0;}if(b.id==='save-workout'){if(openedSessionKey)return;const invalid=[...app.querySelectorAll('input[type=number]')].find(input=>!input.checkValidity());if(invalid){invalid.reportValidity();return;}const key=sessionKey(profile,date,selected);const session=data.sessions[key];if(!session){document.querySelector('#save-workout-message').textContent='Registre uma série antes de salvar um novo treino.';return;}let suffix=1;while(data.sessions[key+':'+suffix])suffix++;const archiveKey=key+':'+suffix;const previousDraft=data.drafts?.[key];data.sessions[archiveKey]={...session,savedAt:new Date().toISOString()};delete data.sessions[key];data.drafts??={};data.drafts[key]={...session,sets:Object.fromEntries(Object.entries(session.sets).map(([id,set])=>[id,{...set,done:false}]))};const saved=persist();if(saved){render();document.querySelector('#save-workout-message').textContent='Treino salvo e encerrado neste dispositivo. '+Object.values(session.sets).filter(set=>set.done).length+' de 12 séries concluídas. As marcações foram limpas para o próximo treino.';document.querySelector('#saved-workout-actions').innerHTML='<button class="secondary" data-resume="'+esc(archiveKey)+'">Ver treino salvo</button>';}else{data.sessions[key]=session;delete data.sessions[archiveKey];if(previousDraft)data.drafts[key]=previousDraft;else delete data.drafts[key];document.querySelector('#save-workout-message').textContent='Não foi possível salvar. Suas marcações foram mantidas.';}}if(b.id==='close-dialog')document.querySelector('dialog').close();if(b.id==='export'){const blob=new Blob([JSON.stringify({version:1,sessions:data.sessions},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`nosso-treino-${today()}.json`;a.click();data.lastBackupAt=new Date().toISOString();if(persist()){document.querySelector('#last-backup').textContent='Última exportação solicitada: '+savedTime({savedAt:data.lastBackupAt})+'. Confira o arquivo na pasta de downloads.';}setTimeout(()=>URL.revokeObjectURL(url),1000);}});
document.addEventListener('input',e=>{const t=e.target;if(cloud?.busy)return;if((openedSessionKey&&!editDraft)||!t.dataset.set)return;const error=document.querySelector('#error-'+t.dataset.set.split(':')[0]);if(!t.checkValidity()){error.textContent=t.validationMessage||'Use um valor entre 0 e 999; repetições e segundos devem ser inteiros.';t.setAttribute?.('aria-invalid','true');return;}error.textContent='';t.removeAttribute?.('aria-invalid');const key=sessionKey(profile,date,selected);const s=editDraft || (data.sessions[key]??=JSON.parse(JSON.stringify(current()||{profile,date,workout:selected,sets:{}})));const v=s.sets[t.dataset.set]??={weight:'',reps:'',done:false};v[t.dataset.field]=t.type==='checkbox'?t.checked:t.value;if(!editDraft)persist();const p=progress(s);document.querySelector('#percent').textContent=p+'%';document.querySelector('#sticky-percent').textContent=p+'%';document.querySelector('#progress-bar').style.width=p+'%';document.querySelector('#complete').hidden=p!==100;const id=t.dataset.set.split(':')[0];document.querySelector('#done-'+id).textContent=[0,1].every(n=>s.sets[`${id}:${n}`]?.done)?'✓ Exercício concluído':'';});
document.addEventListener('change',async e=>{if(e.target.id.startsWith('history-')){const field=e.target.id.slice(8);if(Object.hasOwn(historyFilters,field)){historyFilters[field]=e.target.value;render();}return;}if(e.target.id==='date'){if(!e.target.value||e.target.value>today())return;if(openedSessionKey)return;returnContext=null;date=e.target.value;render();}if(e.target.id==='exercise-select'){evolutionExercise=e.target.value;chart(e.target.value);}if(e.target.id==='import'){try{const file=e.target.files[0];if(!file)return;if(file.size>5e6)throw Error('Arquivo muito grande.');const incoming=validateBackup(JSON.parse(await file.text()));if(cloud?.active&&Object.values(incoming).some(session=>session.profile!==profile))throw Error('Este backup contém outro perfil. Exporte cada perfil separadamente ou importe os dados locais pelo menu Conta.');if(!confirm('Importar os registros deste backup? Registros existentes serão preservados.'))return;const before={...data.sessions};let count=0;for(const [k,s]of Object.entries(incoming))if(!Object.hasOwn(data.sessions,k)){data.sessions[k]=s;count++;}if(persist()){render();document.querySelector('#backup-message').textContent=`${count} registros importados e salvos neste dispositivo.`;}else{data.sessions=before;document.querySelector('#backup-message').textContent='A importação não foi salva. Seus registros anteriores foram mantidos; tente novamente.';}}catch(err){document.querySelector('#backup-message').textContent=err.message;}}});
render();

function showAccount(message='') {
 const dialog=document.querySelector('#account-dialog'),body=document.querySelector('#account-body');
 body.innerHTML=`<span class="eyebrow">SEUS REGISTROS ONLINE</span><h2 id="account-title">Conta e sincronização</h2><p id="account-message" role="status">${esc(message||cloud?.notice||'Conexão online indisponível.')}</p>${cloud?.active?`<p>Conectado como <strong>${esc(cloud.profile)}</strong><br>${esc(cloud.email)}</p><p class="hint">Cada conta tem seus próprios registros. Para trocar de usuário, saia e entre na outra conta.</p><div class="account-actions"><button class="primary" id="cloud-retry">Sincronizar agora</button><button class="secondary" id="cloud-refresh">Carregar versão do servidor</button><button class="secondary" id="cloud-migrate">Importar meus treinos locais</button><button class="secondary" id="cloud-logout">Sair da conta</button></div>`:cloud?.hasSession?`<p>A sessão está conectada, mas os registros ainda não puderam ser carregados.</p><button class="primary" id="cloud-retry">Tentar carregar conta</button> <button class="secondary" id="cloud-logout">Sair</button>`:`<p>Entre para salvar seus treinos online. O histórico local permanece neste aparelho até você escolher importá-lo.</p><form id="account-form"><label>Seu perfil<select id="account-profile" name="profile"><option value="Caio" ${profile==='Caio'?'selected':''}>Caio</option><option value="Nicolli" ${profile==='Nicolli'?'selected':''}>Nicolli</option></select></label><label>E-mail<input name="email" id="account-email" type="email" required autocomplete="email"></label><label>Senha<input name="password" id="account-password" type="password" minlength="8" required autocomplete="current-password"></label><div class="account-actions"><button class="primary" type="submit" name="action" value="login">Entrar</button><button class="secondary" type="submit" name="action" value="signup">Criar conta</button></div></form>`}`;
 if(!dialog.open)dialog.showModal();
}
function switchWorkspace(workspace) {
 // Dados de contas e dados locais usam armazenamentos distintos.
 useWorkspace(workspace?{load:()=>workspace.state,save:state=>cloud.save(state)}:null);
 storageError=false;
 try{data=load();}catch{data={sessions:{}};storageError=true;}
 profile=workspace?.profile||loadProfile();openedSessionKey=null;editDraft=null;returnContext=null;deletedRecord=null;date=today();selected=recommended(date);view='inicio';render();
}
async function handleAccountClick(event){
 const button=event.target.closest('button');if(!button)return;
 if(button.id==='open-account'){if(!leaveRecord())return;showAccount();return;}
 if(button.id==='close-account'){document.querySelector('#account-dialog').close();return;}
 if(!['cloud-retry','cloud-refresh','cloud-migrate','cloud-logout'].includes(button.id))return;
 if(!cloud){showAccount('Não foi possível carregar o módulo online. Atualize a página.');return;}
 button.disabled=true;
 try {
  if(button.id==='cloud-retry'){await cloud.retry();showAccount(cloud.notice);}
  if(button.id==='cloud-refresh'){
   if(editDraft)throw Error('Salve ou cancele a edição antes de atualizar.');
   if(!confirm('Carregar os registros do servidor? Se houver alterações pendentes neste aparelho, uma cópia de recuperação será preservada, mas elas deixarão de aparecer na ficha. Exporte um backup antes se quiser guardá-las em arquivo.'))return;
   await cloud.refresh();showAccount(cloud.notice);
  }
  if(button.id==='cloud-logout'){
   if(cloud.pending&&!confirm('Há alterações ainda não sincronizadas. Elas ficarão guardadas neste aparelho para tentar enviar quando você entrar novamente nesta mesma conta. Sair agora?'))return;
   await cloud.logout();showAccount('Você saiu da conta. Os registros locais deste aparelho estão disponíveis.');
  }
  if(button.id==='cloud-migrate'){
   const guest=JSON.parse(localStorage.getItem(STORAGE_KEY)||'{"sessions":{}}');validateBackup({version:1,sessions:guest.sessions});
   const incoming=Object.entries(guest.sessions).filter(([,session])=>session.profile===cloud.profile);
   if(!incoming.length){showAccount('Não há treinos locais deste perfil nesta origem. Se os registros estavam em outro endereço, exporte um backup lá.');return;}
   if(!confirm('Importar '+incoming.length+' treino(s) locais de '+cloud.profile+' para esta conta no Supabase? Registros com a mesma identificação serão preservados e os dados locais continuarão neste aparelho.'))return;
   const previous=data.sessions;data.sessions={...Object.fromEntries(incoming),...data.sessions};
   if(!persist()){data.sessions=previous;throw Error('Não foi possível salvar a importação localmente.');}
   render();await cloud.retry();showAccount(cloud.notice);
  }
 }catch(error){showAccount(cloud.friendly(error));}
 finally{button.disabled=false;}
}
document.addEventListener('submit',async event=>{
 if(event.target.id!=='account-form')return;event.preventDefault();
 const form=event.target;if(!form.reportValidity())return;
 if(!cloud){showAccount('O módulo online não carregou. Atualize a página.');return;}
 const email=document.querySelector('#account-email').value.trim(),password=document.querySelector('#account-password').value,name=document.querySelector('#account-profile').value;
 const buttons=form.querySelectorAll('button');buttons.forEach(button=>button.disabled=true);
 document.querySelector('#account-message').textContent='Conectando…';
 try{
  let message;
  if(event.submitter?.value==='signup')message=await cloud.signup(email,password,name);
  else{await cloud.login(email,password,name);message=cloud.notice;}
  showAccount(message);
 }catch(error){document.querySelector('#account-message').textContent=cloud.friendly(error);}
 finally{const passwordField=document.querySelector('#account-password');if(passwordField)passwordField.value='';buttons.forEach(button=>button.disabled=false);}
});
if(cloud)cloud.start({workspace:switchWorkspace,status:(message,error)=>{status.textContent='● '+message;status.classList.toggle('error',Boolean(error));const dialog=document.querySelector('#account-dialog');if(dialog?.open){const text=document.querySelector('#account-message');if(text)text.textContent=message;}}}).catch(()=>{});

})();
